on conflict (id) do nothing;
insert into public.lesson_sentences (lesson_id, position, text, translation_vi)
select 'b0000000-0000-4000-8000-000000000e01'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'I usually wake up at half past six.', 'Tôi thường thức dậy lúc sáu giờ rưỡi.'),
  (2, 'The first thing I do is drink a glass of water.', 'Việc đầu tiên tôi làm là uống một cốc nước.'),
  (3, 'Then I take a quick shower and get dressed.', 'Sau đó tôi tắm nhanh và mặc quần áo.'),
  (4, 'I don''t have much time for breakfast on weekdays.', 'Vào các ngày trong tuần tôi không có nhiều thời gian ăn sáng.'),
  (5, 'Most mornings I just have toast and a cup of coffee.', 'Hầu hết các buổi sáng tôi chỉ ăn bánh mì nướng và một tách cà phê.'),
  (6, 'I leave the house at about a quarter past seven.', 'Tôi ra khỏi nhà vào khoảng bảy giờ mười lăm.'),
  (7, 'It takes me twenty minutes to get to work by bus.', 'Tôi mất hai mươi phút để đi làm bằng xe buýt.'),
  (8, 'On the bus, I listen to podcasts to practise my listening.', 'Trên xe buýt, tôi nghe podcast để luyện nghe.'),
  (9, 'On Sundays, I sleep in and make a big breakfast.', 'Vào Chủ nhật, tôi ngủ nướng và làm một bữa sáng thịnh soạn.'),
  (10, 'A good morning routine makes the whole day better.', 'Một thói quen buổi sáng tốt giúp cả ngày tốt hơn.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e01');

insert into public.lessons (id, title, description, language, level, hsk_level, topic_id, source, difficulty, is_published, is_sample)
select 'b0000000-0000-4000-8000-000000000e02', 'Lost Luggage', 'A suitcase goes missing after a flight — past tenses and reported speech.', 'en', 'intermediate', null, id, 'LinguaFlow', 3, true, true
from public.topics where slug = 'travel'
on conflict (id) do nothing;
insert into public.lesson_sentences (lesson_id, position, text, translation_vi)
select 'b0000000-0000-4000-8000-000000000e02'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'When we landed, I realised my suitcase hadn''t arrived.', 'Khi hạ cánh, tôi nhận ra vali của mình chưa đến.'),
  (2, 'I went to the baggage desk and explained the problem.', 'Tôi đến quầy hành lý và giải thích vấn đề.'),
  (3, 'The woman asked me to fill in a form with my contact details.', 'Người phụ nữ yêu cầu tôi điền vào mẫu đơn với thông tin liên lạc.'),
  (4, 'She said it had probably been put on the wrong flight.', 'Cô ấy nói có lẽ nó đã bị đưa lên nhầm chuyến bay.'),
  (5, 'They promised to deliver it to my hotel within two days.', 'Họ hứa sẽ giao nó đến khách sạn của tôi trong vòng hai ngày.'),
  (6, 'Luckily, I had packed a change of clothes in my hand luggage.', 'May mắn là tôi đã để một bộ quần áo thay trong hành lý xách tay.'),
  (7, 'The next evening, the receptionist called to say it had arrived.', 'Tối hôm sau, lễ tân gọi điện báo rằng nó đã đến.'),
  (8, 'Since then, I''ve always kept the essentials in my backpack.', 'Từ đó, tôi luôn để những thứ thiết yếu trong ba lô.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e02');

insert into public.lessons (id, title, description, language, level, hsk_level, topic_id, source, difficulty, is_published, is_sample)
select 'b0000000-0000-4000-8000-000000000e03', 'Working From Home', 'Benefits and challenges of remote and hybrid work.', 'en', 'upper_intermediate', null, id, 'LinguaFlow', 4, true, true
from public.topics where slug = 'business-career'
on conflict (id) do nothing;
insert into public.lesson_sentences (lesson_id, position, text, translation_vi)
select 'b0000000-0000-4000-8000-000000000e03'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'Over the past few years, remote work has become far more common.', 'Trong vài năm qua, làm việc từ xa đã trở nên phổ biến hơn nhiều.'),
  (2, 'Many employees appreciate not having to commute every day.', 'Nhiều nhân viên đánh giá cao việc không phải đi lại mỗi ngày.'),
  (3, 'However, some find it hard to separate work from their personal life.', 'Tuy nhiên, một số người thấy khó tách công việc khỏi cuộc sống cá nhân.'),
  (4, 'Without clear boundaries, the working day can easily stretch into the evening.', 'Nếu không có ranh giới rõ ràng, ngày làm việc dễ kéo dài sang buổi tối.'),
  (5, 'Managers, on the other hand, worry about communication and team spirit.', 'Mặt khác, các nhà quản lý lo ngại về giao tiếp và tinh thần đồng đội.'),
  (6, 'That''s why a lot of companies have adopted a hybrid model.', 'Đó là lý do nhiều công ty đã áp dụng mô hình kết hợp.'),
  (7, 'Staff spend two or three days in the office and work from home the rest of the week.', 'Nhân viên dành hai hoặc ba ngày ở văn phòng và làm việc tại nhà những ngày còn lại.'),
  (8, 'Whether this arrangement will last remains to be seen.', 'Liệu cách sắp xếp này có kéo dài hay không thì vẫn còn phải chờ xem.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e03');

insert into public.lessons (id, title, description, language, level, hsk_level, topic_id, source, difficulty, is_published, is_sample)
select 'b0000000-0000-4000-8000-000000000e04', 'How Memory Works', 'Why we forget, and what research says about studying smarter.', 'en', 'advanced', null, id, 'LinguaFlow', 5, true, true
from public.topics where slug = 'education'
on conflict (id) do nothing;
insert into public.lesson_sentences (lesson_id, position, text, translation_vi)
select 'b0000000-0000-4000-8000-000000000e04'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'Contrary to popular belief, memory is not a perfect recording of the past.', 'Trái với niềm tin phổ biến, trí nhớ không phải là bản ghi hoàn hảo về quá khứ.'),
  (2, 'Each time we recall an event, our brain reconstructs it from scattered fragments.', 'Mỗi lần nhớ lại một sự kiện, não bộ tái dựng nó từ những mảnh rời rạc.'),
  (3, 'This is why two witnesses can give strikingly different accounts of the same incident.', 'Đây là lý do hai nhân chứng có thể kể lại cùng một sự việc khác nhau đến bất ngờ.'),
  (4, 'Researchers have found that sleep plays a crucial role in consolidating new information.', 'Các nhà nghiên cứu phát hiện giấc ngủ đóng vai trò then chốt trong việc củng cố thông tin mới.'),
  (5, 'Spacing out practice sessions is considerably more effective than cramming.', 'Giãn cách các buổi luyện tập hiệu quả hơn đáng kể so với học nhồi nhét.'),
  (6, 'Testing yourself, rather than simply rereading notes, strengthens long-term retention.', 'Tự kiểm tra bản thân, thay vì chỉ đọc lại ghi chép, giúp ghi nhớ lâu dài tốt hơn.'),
  (7, 'Emotionally charged experiences also tend to be remembered more vividly.', 'Những trải nghiệm giàu cảm xúc cũng thường được nhớ rõ nét hơn.'),
  (8, 'Understanding these mechanisms can help learners study smarter rather than harder.', 'Hiểu những cơ chế này giúp người học học thông minh hơn thay vì vất vả hơn.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e04');


